evals.prompt:
아래 음원 스트리밍 서비스의 스키마와 쿼리를 DB 설계 관점에서 리뷰해줘:

```sql
CREATE TABLE track (
    title VARCHAR(200),
    artist_names VARCHAR(500),       -- '아이유, 헤이즈, BE'O' 처럼 콤마 구분
    album_title VARCHAR(200),
    genre_path VARCHAR(500),         -- '일렉트로닉/하우스/딥하우스'
    duration_sec INT,
    play_count BIGINT DEFAULT 0,     -- 재생할 때마다 UPDATE
    like_count BIGINT DEFAULT 0,     -- 좋아요할 때마다 UPDATE
    created_at TIMESTAMP
);

CREATE TABLE play_event (
    user_id BIGINT,
    track_title VARCHAR(200),        -- track FK 없이 제목 문자열로 보관
    played_at TIMESTAMP
);

CREATE TABLE playlist_track (
    playlist_id BIGINT,
    track_title VARCHAR(200),
    position INT
    -- PK 없음, 인덱스 없음
);

-- 자주 실행되는 쿼리:
-- 1) 사용자의 최근 30일 재생 목록
SELECT * FROM play_event
WHERE user_id = ? AND played_at >= NOW() - INTERVAL '30 days';

-- 2) 화면 렌더링: 플레이리스트의 모든 트랙 + 각 트랙의 아티스트
for pt in playlist_tracks:
    track = SELECT * FROM track WHERE title = pt.track_title;
    print(track.artist_names)

-- 3) 결제 처리 (READ UNCOMMITTED 사용 중)
BEGIN ISOLATION LEVEL READ UNCOMMITTED;
  SELECT balance FROM subscription WHERE user_id = ?;
  UPDATE subscription SET balance = balance - ? WHERE user_id = ?;
COMMIT;
```
